/**
 * Stage Synth — prototype of a SHARED mechanical/acoustic resonance subsystem.
 * No external samples, no third-party dependencies. This is intentionally NOT
 * a complete piano synthesizer. Designed to receive the DRY bridge vibration
 * generated by another hammer/string engine and return a resonant BODY ONLY.
 *
 * Mechanics modelled: 88 damper gates, CC64 sustain, a lightweight bank of
 * sympathetic string modes, and globally shared bridge/soundboard resonances.
 * v1.12.1 also returns bounded velocity-proportional bridge reaction. To form a
 * genuine two-way loop, use CoupledPianoBus in the SAME audio callback as the
 * primary string model, not a WebAudio feedback cable.
 * A subsequent integration should tune physical parameters from dry notes.
 */

const TWO_PI = Math.PI * 2;
const constrain = (x, a, b) => Math.max(a, Math.min(b, x));
const midiHz = midi => 440 * 2 ** ((midi - 69) / 12);

// Low and middle soundboard resonances are broad bands, NOT fixed piano notes.
const BOARD_HZ = [91, 148, 225, 323, 465, 618, 826, 1138, 1548, 1980, 2520, 3275];
const BODY_TAU = [0.37, 0.45, 0.49, 0.39, 0.32, 0.30, 0.28, 0.23, 0.18, 0.16, 0.14, 0.12];

export class PianoResonanceBody {
  constructor({sampleRate=48000, divisor=4, sympathetic=0.22, body=0.20, mechanical=0, bridgeLoad=0.20}={}) {
    if (!Number.isFinite(sampleRate) || sampleRate < 22050) throw new RangeError('sampleRate must be >= 22050');
    if (!Number.isInteger(divisor) || divisor < 1 || divisor > 8) throw new RangeError('divisor must be 1..8');
    this.sampleRate=sampleRate;
    this.divisor=divisor;
    this.rate=sampleRate/divisor;
    this.sympathetic=constrain(sympathetic,0,1);
    this.body=constrain(body,0,1);
    this.mechanical=constrain(mechanical,0,1);
    this.bridgeLoad=constrain(bridgeLoad,0,0.4);
    this.keys=new Uint8Array(88);
    this.pedal=0;
    this.tick=0;
    this.smoothInput=0;
    this.acc=0;
    this.holdL=0;
    this.holdR=0;
    this.wetL=0;this.wetR=0;this.reaction=0;
    this.prevDisplacement=0;this.reactionTarget=0;
    this.mechanics=0;
    this.noiseSeed=0xace2;
    // Two resonant partials for each of 88 keys; their dampers are shared.
    const n=176;
    this.y1=new Float64Array(n);
    this.y2=new Float64Array(n);
    this.c=new Float64Array(n);
    this.rOpen=new Float64Array(n);
    this.rClosed=new Float64Array(n);
    this.g=new Float64Array(n);
    this.enabled=new Uint8Array(n);
    this.stringPan=new Float32Array(n);
    for (let k=0; k<88; k++) {
      const f=midiHz(k+21);
      const x=(k-43.5)/43.5;
      // Not an empirical fit: an initial, bounded inharmonicity placeholder.
      const stiffness = 1.0e-4*(1+0.80*x*x);
      for(let m=1; m<=2; m++){
        const j=k*2+m-1;
        const fm=f*m*Math.sqrt(1+stiffness*m*m);
        if (fm > 0.40*this.rate) continue;
        this.enabled[j]=1;
        const w=TWO_PI*fm/this.rate;
        this.c[j]=2*Math.cos(w);
        // A damper physically touches a string: lose energy quickly when closed.
        // Uppermost notes have no dampers, accounted for by keyGate().
        this.rOpen[j]=Math.exp(-1/(this.rate*(m===1?3.5:1.7)));
        this.rClosed[j]=Math.exp(-1/(this.rate*0.038));
        this.g[j]=Math.sin(w)*(1-this.rOpen[j])*(m===1?0.65:0.16);
        this.stringPan[j]=x*0.65;
      }
    }
    const b=BOARD_HZ.length;
    this.board1=new Float64Array(b);
    this.board2=new Float64Array(b);
    this.boardC=new Float64Array(b);
    this.boardR=new Float64Array(b);
    this.boardG=new Float64Array(b);
    this.boardPan=new Float32Array(b);
    for(let i=0;i<b;i++){
      let w=TWO_PI*BOARD_HZ[i]/this.rate;
      this.boardC[i]=2*Math.cos(w);
      this.boardR[i]=Math.exp(-1/(this.rate*BODY_TAU[i]));
      this.boardG[i]=Math.sin(w)*(1-this.boardR[i])*(i<5?0.80:0.37);
      this.boardPan[i]=(i%2===0?-0.5:0.5)*(0.4+0.6*(i/b));
    }
  }
  _idx(note){return Math.round(note)-21}
  noteOn(note, velocity=90){
    const k=this._idx(note);if(k<0||k>=88)return;
    this.keys[k]=1;
    this.mechanics+=this.mechanical*constrain(velocity,1,127)/127*0.025;
  }
  noteOff(note){
    const k=this._idx(note);if(k<0||k>=88)return;
    this.keys[k]=0;
    if(this.pedal<0.5)this.mechanics-=this.mechanical*0.006;
  }
  /** MIDI CC64 0-127; 64+ is pedal down; 0..63 scales partial damper lift. */
  setSustain(value){this.pedal=constrain(value,0,127)/127}
  /** To reset held keys after MIDI disconnect or panic, without clearing board tails. */
  allKeysUp(){this.keys.fill(0);this.pedal=0}
  reset(){this.allKeysUp();this.y1.fill(0);this.y2.fill(0);this.board1.fill(0);this.board2.fill(0);this.acc=this.smoothInput=this.holdL=this.holdR=this.mechanics=this.tick=0;this.wetL=this.wetR=this.reaction=this.prevDisplacement=this.reactionTarget=0}
  keyGate(k){return k>=88-18 ? 1 : Math.max(this.keys[k],this.pedal)}
  /**
   * Advance ONE sample of dry bridge motion from the PRIMARY STRING MODEL.
   * Reads the driving bridge velocity and exposes:
   *   .wetL/.wetR  radiated board + sympathy;
   *   .reaction     bounded opposing bridge velocity to feed into the SAME
   *                 waveguide at the following sample.
   * A separate WebAudio node cannot safely close this sub-128-sample loop:
   * use CoupledPianoBus with a synchronous primary string adapter instead.
   * This routine allocates no arrays/objects on the audio thread.
   */
  step(inputL,inputR=inputL){
    const xl=Number.isFinite(inputL)?constrain(inputL,-2,2):0;
    const xr=Number.isFinite(inputR)?constrain(inputR,-2,2):xl;
    const input=(xl+xr)*.5;
    // Lowpass before 4:1 decimation. Coupling always starts from DRY bridge
    // velocity, never from room reverb or master output.
    this.smoothInput+=.25*(input-this.smoothInput);
    this.acc+=this.smoothInput;
    if(++this.tick>=this.divisor){
      const bridge=this.acc/this.divisor;
      this.tick=0;this.acc=0;
      let sL=0,sR=0;
      for(let k=0;k<88;k++){
        const gate=this.keyGate(k);
        const j0=k*2;
        for(let m=0;m<2;m++){
          const j=j0+m;
          if(!this.enabled[j])continue;
          // Damper coupling is continuous; closed strings release in ~38 ms.
          const r=this.rClosed[j]+gate*(this.rOpen[j]-this.rClosed[j]);
          const y=this.c[j]*r*this.y1[j]-r*r*this.y2[j]+this.g[j]*bridge*gate;
          this.y2[j]=this.y1[j];this.y1[j]=y;
          const a=y*(m===0?1:.28);
          sL+=a*(1-.4*this.stringPan[j]);
          sR+=a*(1+.4*this.stringPan[j]);
        }
      }
      let bL=0,bR=0;
      for(let j=0;j<this.board1.length;j++){
        const r=this.boardR[j];
        const y=this.boardC[j]*r*this.board1[j]-r*r*this.board2[j]+this.boardG[j]*bridge;
        this.board2[j]=this.board1[j];this.board1[j]=y;
        bL+=y*(1-.3*this.boardPan[j]);
        bR+=y*(1+.3*this.boardPan[j]);
      }
      const displacement=(bL+bR)*.5;
      const velocity=displacement-this.prevDisplacement;
      this.prevDisplacement=displacement;
      // Opposing impedance: a moving bridge is loaded by the soundboard and
      // sympathetic strings. Small dimensionless gain, clamped to cap energy.
      // Calibration of mechanical impedance is NOT yet done.
      const sympatheticVelocity=(sL+sR)*.5;
      this.reactionTarget=constrain(-this.bridgeLoad*(0.65*velocity+0.016*sympatheticVelocity),-0.08,0.08);
      this.holdL=this.body*bL+this.sympathetic*sL;
      this.holdR=this.body*bR+this.sympathetic*sR;
    }
    this.reaction+=.18*(this.reactionTarget-this.reaction);
    if(Math.abs(this.reaction)<1e-17)this.reaction=0;
    // Mechanical noise remains optional, never continuously injected.
    let noise=0;
    if(this.mechanics>1e-8){
      this.noiseSeed^=this.noiseSeed<<13;
      this.noiseSeed^=this.noiseSeed>>>17;
      this.noiseSeed^=this.noiseSeed<<5;
      noise=(this.noiseSeed/2147483648)*this.mechanics;
      this.mechanics*=.996;
    }else this.mechanics=0;
    this.wetL=this.holdL+noise;
    this.wetR=this.holdR+noise;
  }
  /**
   * Compatible with the former wet-only prototype; optional Float32Array
   * bridgeReturn receives a bounded feedback signal. It will ONLY change the
   * dry string response if the host routes it back into the primary engine.
   */
  process(inputL,inputR,wetL,wetR,bridgeReturn=null){
    const n=inputL.length;
    if(inputR.length!==n||wetL.length!==n||wetR.length!==n||(bridgeReturn&&bridgeReturn.length!==n))throw new RangeError('block lengths differ');
    for(let i=0;i<n;i++){
      this.step(inputL[i],inputR[i]);
      wetL[i]=this.wetL;wetR[i]=this.wetR;
      if(bridgeReturn)bridgeReturn[i]=this.reaction;
    }
  }
}
